mapper.update:
UPDATE purchase_requests pr
SET status = #{decision},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE pr.id = #{requestId}
  AND pr.status = 'SUBMITTED'
  AND pr.version = #{expectedVersion}
  AND EXISTS (
      SELECT 1
      FROM approver_department_scopes scope
      WHERE scope.user_id = #{approverId}
        AND scope.department_id = pr.department_id
  )
